@startuml

class Person {
  + VAT number
  + name
  + phone number
}

class Customer extends Person {
  + address
}

class Courier extends Person {}

class Package {
  + identifier code
  + weight
  + delivery type
}

class DeliveryCenter {
  + name
  + address
}

Customer "1" -- "1" DeliveryCenter : associated with
Customer "1" -- "*" Package : sends
Customer "1" -- "*" Package : receives
Package "*" -- "1" DeliveryCenter : delivered to
Package "*" -- "1" DeliveryCenter : routed through
Courier "1" -- "1" DeliveryCenter : works for
Courier "1" -- "*" Package : assigned to

@enduml

